  applyCard("sucrose","sucrose","sucrose",{"id":"sucrose-table-sugar","definition":"A natural sugar found in plants and commonly sold as table sugar.","synonym":"table sugar","example":"«sucrose» is the scientific name for ordinary table sugar.","exampleSynonymText":"«table sugar» is the scientific name for ordinary table sugar."});
  applyCard("spanking-22","spanking-22","spanking",{"id":"spanking-series-of-hits-as-punishment","definition":"A series of hits on the bottom given as punishment.","synonym":"smacking","example":"«spanking» was once used as punishment for children.","exampleSynonymText":"«smacking» was once used as punishment for children."});
