  applyCard("guitar-player","guitar-player","guitar player",{"id":"guitar-player-person-who-plays-the-guitar","definition":"A person who plays the guitar.","synonym":"guitarist","example":"The guitar player practiced before the concert.","exampleSynonymText":"The guitarist practiced before the concert."});
  applyCard("sizing","sizing","Sizing",{"id":"sizing-measuring-the-size-of-something","definition":"The act of finding or setting the size of something.","synonym":"measuring","example":"“Sizing” the room helped us choose a table.","exampleSynonymText":"“measuring” the room helped us choose a table."});
