  applyCard("spark-arrester","spark-arrester","Spark arrester",{"id":"spark-arrester-device-that-stops-flying-sparks","definition":"A device that stops sparks flying from a chimney or engine.","synonym":"spark guard","example":"A “Spark arrester” kept embers from leaving the stove pipe.","exampleSynonymText":"A “spark guard” kept embers from leaving the stove pipe."});
  applyCard("funded","funded","Funded",{"id":"funded-provided-with-money-for-a-purpose","definition":"Provided with money for a project, activity, or organization.","synonym":"financed","example":"The “Funded” program offered free lessons to children.","exampleSynonymText":"The “financed” program offered free lessons to children."});
  applyCard("conduct","conduct","Conduct",{"id":"conduct-persons-behavior","definition":"The way a person behaves, especially in a particular situation.","synonym":"behavior","example":"“Conduct” during the test must remain respectful.","exampleSynonymText":"“behavior” during the test must remain respectful."});
  applyCard("urgent-2","urgent-2","Urgent",{"id":"urgent-needing-immediate-action-or-attention","definition":"Needing immediate action or attention because time is limited.","synonym":"pressing","example":"“Urgent” repairs were needed after the storm.","exampleSynonymText":"“pressing” repairs were needed after the storm."});
