  applyCard("resemble-2","resemble-2","resemble",{"id":"resemble-look-or-be-similar-to-something","definition":"To look like or share important features with someone or something.","synonym":"look like","example":"The twins resemble their grandmother.","exampleSynonymText":"The twins look like their grandmother."});
  applyCard("constrict-4","constrict-4","Constrict",{"id":"constrict-make-narrower-or-tighter","definition":"To make something narrower or tighter by squeezing it.","synonym":"tighten","example":"“Constrict” the band gently around the bundle.","exampleSynonymText":"“tighten” the band gently around the bundle."});
